#!/usr/bin/env node
// One maintained staff back-office: backend/public (served same-origin by
// the API on Railway). The Vercel site ships a copy under web/public so
// /admin-dashboard.html also works there; that copy is GENERATED by this
// script and must never be edited by hand. The only difference is how
// api.js chooses the API host (Vercel has no /api of its own).
//
//   node scripts/sync-static-admin.mjs          write web/public from backend/public
//   node scripts/sync-static-admin.mjs --check  exit 1 if web/public is out of date
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const SOURCE_DIR = path.join(ROOT, "backend", "public");
export const TARGET_DIR = path.join(ROOT, "web", "public");
const BANNER_TEXT = "GENERATED from backend/public by scripts/sync-static-admin.mjs. Do not edit here: edit backend/public and run `node scripts/sync-static-admin.mjs`.";

// The Vercel copy's API host selection (unchanged from the hand-maintained
// web/public/assets/api.js it replaces): production hosts use the Railway
// production API, localhost uses a local backend, every preview/branch host
// fails closed to same-origin /api so it can never write to Production.
const VERCEL_API_BASE = `// This copy of api.js is served by the Vercel-hosted marketing site
// (web/), which has no backend of its own — unlike backend/public/assets/api.js,
// which the Express backend serves same-origin alongside its own API (see
// backend/src/app.js's static-serving comment), a relative "/api" here
// resolves against Vercel itself and 404s. There's no build-time env
// injection into files under web/public (Next.js serves them verbatim), so
// Production uses the Railway API only on explicitly approved production
// hostnames. Every PR/branch preview fails closed to same-origin /api so QA
// can never mutate Production accidentally.
const PRODUCTION_API_BASE = "https://nasaem-platform-production.up.railway.app/api";
const PRODUCTION_WEB_HOSTS = new Set([
  "nasaem-alharamain.com",
  "www.nasaem-alharamain.com",
  "nasaem-platform.vercel.app",
  "nasaem-platform-abdalhgali-cmds-projects.vercel.app",
]);
const LOCAL_WEB_HOSTS = new Set(["localhost", "127.0.0.1", "::1"]);
const API_BASE = PRODUCTION_WEB_HOSTS.has(window.location.hostname)
  ? PRODUCTION_API_BASE
  : LOCAL_WEB_HOSTS.has(window.location.hostname)
    ? "http://localhost:5000/api"
    : "/api";`;

function listFiles(dir, base = dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    return entry.isDirectory() ? listFiles(full, base) : [path.relative(base, full)];
  });
}

function transform(relativePath, content) {
  if (relativePath.endsWith(".html")) {
    return content.replace(/^<!doctype html>\n/i, (doctype) => `${doctype}<!-- ${BANNER_TEXT} -->\n`);
  }
  let body = content;
  if (relativePath === path.join("assets", "api.js")) {
    if (!body.includes('const API_BASE = "/api";')) throw new Error("backend/public/assets/api.js no longer defines API_BASE as expected");
    body = body.replace('const API_BASE = "/api";', VERCEL_API_BASE);
  }
  return `/* ${BANNER_TEXT} */\n${body}`;
}

export function expectedOutputs() {
  return listFiles(SOURCE_DIR).map((relativePath) => ({
    relativePath,
    content: transform(relativePath, fs.readFileSync(path.join(SOURCE_DIR, relativePath), "utf8")),
  }));
}

// Generated files that are no longer in the source (e.g. a removed script)
// are recognised by their banner and reported/removed too.
export function staleGeneratedFiles(outputs = expectedOutputs()) {
  const expected = new Set(outputs.map((o) => o.relativePath));
  return listFiles(TARGET_DIR)
    .filter((relativePath) => /\.(js|css|html)$/.test(relativePath) && !expected.has(relativePath))
    .filter((relativePath) => fs.readFileSync(path.join(TARGET_DIR, relativePath), "utf8").includes("GENERATED from backend/public"));
}

export function checkSync() {
  const outputs = expectedOutputs();
  const outdated = outputs
    .filter(({ relativePath, content }) => {
      const target = path.join(TARGET_DIR, relativePath);
      return !fs.existsSync(target) || fs.readFileSync(target, "utf8") !== content;
    })
    .map((o) => o.relativePath);
  return { outdated, stale: staleGeneratedFiles(outputs) };
}

export function writeSync() {
  const outputs = expectedOutputs();
  for (const { relativePath, content } of outputs) {
    const target = path.join(TARGET_DIR, relativePath);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, content);
  }
  for (const relativePath of staleGeneratedFiles(outputs)) fs.unlinkSync(path.join(TARGET_DIR, relativePath));
  return outputs.length;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  if (process.argv.includes("--check")) {
    const { outdated, stale } = checkSync();
    if (outdated.length || stale.length) {
      console.error("web/public is out of date with backend/public. Run: node scripts/sync-static-admin.mjs");
      for (const f of outdated) console.error(`  outdated: web/public/${f}`);
      for (const f of stale) console.error(`  stale:    web/public/${f}`);
      process.exit(1);
    }
    console.log("web/public matches backend/public.");
  } else {
    console.log(`Wrote ${writeSync()} files to web/public.`);
  }
}
